// Crossfire/CfPlatform.cs — portable helpers generated by Crossfire.
// Replaces common Windows-only .NET idioms (Registry settings, shell launch,
// hard-coded paths) with APIs that work on Windows, macOS, Linux and FreeBSD.
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Text.Json;

namespace Crossfire
{
    public static class CfPlatform
    {
        public static bool IsWindows => OperatingSystem.IsWindows();
        public static bool IsMacOS => OperatingSystem.IsMacOS();
        public static bool IsLinux => OperatingSystem.IsLinux();
        public static bool IsFreeBSD => OperatingSystem.IsFreeBSD();

        /// <summary>%APPDATA% / ~/Library/Application Support / $XDG_DATA_HOME.</summary>
        public static string UserDataDir
        {
            get
            {
                if (IsMacOS)
                    return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Library", "Application Support");
                if (IsWindows)
                    return Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                var xdg = Environment.GetEnvironmentVariable("XDG_DATA_HOME");
                return string.IsNullOrEmpty(xdg)
                    ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".local", "share")
                    : xdg;
            }
        }

        public static string HomeDir => Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        public static string TempDir => Path.GetTempPath();
        public static string AppDir => AppContext.BaseDirectory;

        /// <summary>Open a file, folder or URL with the default handler.</summary>
        public static void OpenPath(string pathOrUrl)
        {
            if (IsWindows)
            {
                Process.Start(new ProcessStartInfo(pathOrUrl) { UseShellExecute = true });
                return;
            }
            var tool = IsMacOS ? "open" : "xdg-open";
            var psi = new ProcessStartInfo(tool) { UseShellExecute = false };
            psi.ArgumentList.Add(pathOrUrl);
            Process.Start(psi);
        }
    }

    /// <summary>
    /// Small JSON-backed settings store, a portable stand-in for
    /// Registry.CurrentUser.CreateSubKey("Software\\App").
    /// </summary>
    public sealed class CfSettings
    {
        private readonly string _file;
        private readonly Dictionary<string, JsonElement> _values;

        private CfSettings(string file, Dictionary<string, JsonElement> values)
        {
            _file = file;
            _values = values;
        }

        public static CfSettings Load(string appName)
        {
            var dir = Path.Combine(CfPlatform.UserDataDir, appName);
            Directory.CreateDirectory(dir);
            var file = Path.Combine(dir, "settings.json");
            var values = new Dictionary<string, JsonElement>();
            if (File.Exists(file))
            {
                try
                {
                    values = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(File.ReadAllText(file)) ?? values;
                }
                catch (JsonException) { }
            }
            return new CfSettings(file, values);
        }

        public T Get<T>(string name, T fallback)
        {
            if (_values.TryGetValue(name, out var el))
            {
                try { return el.Deserialize<T>() ?? fallback; } catch (JsonException) { }
            }
            return fallback;
        }

        public object? GetValue(string name, object? fallback = null) =>
            _values.TryGetValue(name, out var el) ? el.ToString() : fallback;

        public void Set<T>(string name, T value)
        {
            _values[name] = JsonSerializer.SerializeToElement(value);
            Save();
        }

        public void SetValue(string name, object value) => Set(name, value);

        public void Save() =>
            File.WriteAllText(_file, JsonSerializer.Serialize(_values, new JsonSerializerOptions { WriteIndented = true }));
    }
}
